r_category, pi.source_section, sa.source_section, gi.source_section, gb.source_section) as gstr_category, COALESCE(pi.source_section, gi.source_section, gb.source_section, sa.source_section) as gst_type, COALESCE(gi.itc_available, sa.itc_available) as gstr2a_itc_available, COALESCE(gi.itc_eligibility, sa.itc_eligibility) as gstr2a_itc_eligibility, COALESCE(gi.itc_reason, sa.itc_reason) as gstr2a_itc_reason, COALESCE(pi.place_of_supply, sa.place_of_supply) as purchase_pos, COALESCE(gi.place_of_supply, sa.place_of_supply) as gstr2a_pos, COALESCE(rs.recon_status, 'pending') as reconciliation_status from "reconciliation_results_2a" as "rr" left join "reconciliation_runs" as "run" on "rr"."recon_run_id" = "run"."id" left join "normalized_gstr2a_invoices" as "gi" on "rr"."gstr2a_invoice_id" = "gi"."id" left join "purchase_vouchers" as "pi" on "rr"."purchase_invoice_id" = "pi"."id" left join "normalized_gstr2a_invoices" as "sa" on "rr"."gstr2a_source_id" = "sa"."id" left join "normalized_gstr2b_invoices" as "gb" on "rr"."gstr2b_invoice_id" = "gb"."id" left join "reconciliation_status_2a_vs_2b" as "rs" on "rr"."workspace_id" = "rs"."workspace_id" and ("rr"."gstr2a_invoice_id" = "rs"."gstr2a_invoice_id" or "rr"."gstr2b_invoice_id" = "rs"."gstr2b_invoice_id") where "rr"."workspace_id" = '87909bb9-c559-4794-8a0e-15446afc67d5' and "run"."run_type" in ('PURCHASE_2A', 'GSTR2A_VS_GSTR2B', 'PURCHASE_2A_VS_2B') and ((EXTRACT(YEAR FROM COALESCE(pi.supplier_invoice_date, gi.document_date, gb.document_date, sa.document_date)) = 2025 AND EXTRACT(MONTH FROM COALESCE(pi.supplier_invoice_date, gi.document_date, gb.document_date, sa.document_date)) >= 4)
